% lc_mnn.pl - MNN: a small, manual neural network in pure Prolog
%
% An MNN is a one-hidden-layer network written out by hand (no libraries),
% small enough to read: net(W1, B1, W2, B2) with tanh hidden units and a
% softmax output.  Lucian CI/CD 2 uses MNNs to rank choices:
%   - lc_s2a2:   which instruction to try first, from features of a spec
%   - lc_debug:  which kind of repair to try first, from features of a
%                failing test (wrong sign, off by a constant, error, ...)
% Both are trained on corpora generated by the system itself (run an
% instruction on random inputs; plant a bug and record what fixed it).
%
% mnn_explain/2 turns a trained network back into readable Prolog rules,
% in the spirit of reverse-engineering neural networks into code:
%   prefers(reverse) :- feature(out_same_length), feature(out_permutation).

:- module(lc_mnn,
	  [ mnn_new/5,        % +NIn, +NHidden, +NOut, +Seed, -Net
	    mnn_train/5,      % +Net0, +Data[X-Class], +Epochs, +Rate, -Net
	    mnn_predict/3,    % +Net, +X, -Probs
	    mnn_rank/4,       % +Net, +X, +Classes, -RankedClasses
	    mnn_accuracy/3,   % +Net, +Data, -Accuracy
	    mnn_explain/4,    % +Net, +FeatureNames, +ClassNames, -Rules
	    mnn_save/2,       % +File, +mnn(Name, Features, Classes, Net)
	    mnn_load/2        % +File, -mnn(Name, Features, Classes, Net)
	  ]).

:- use_module(library(lists)).
:- use_module(library(apply)).
:- use_module(library(random)).
:- use_module(library(pairs)).

mnn_new(NIn, NH, NOut, Seed, net(W1, B1, W2, B2)) :-
	set_random(seed(Seed)),
	S1 is 1/sqrt(NIn), S2 is 1/sqrt(NH),
	matrix(NH, NIn, S1, W1), length(B1, NH), maplist(=(0.0), B1),
	matrix(NOut, NH, S2, W2), length(B2, NOut), maplist(=(0.0), B2).

matrix(R, C, S, M) :-
	length(M, R),
	maplist([Row]>>( length(Row, C), maplist([W]>>( random(X), W is (2*X-1)*S ), Row) ), M).

% Plain recursion (no lambdas) keeps training fast.
dot(Ws, Xs, D) :- dot(Ws, Xs, 0.0, D).
dot([], [], D, D).
dot([W|Ws], [X|Xs], A0, D) :- A is A0+W*X, dot(Ws, Xs, A, D).

hidden([], [], _, []).
hidden([Row|Rows], [B|Bs], X, [H|Hs]) :- dot(Row, X, Z), H is tanh(Z+B), hidden(Rows, Bs, X, Hs).

linear([], [], _, []).
linear([Row|Rows], [B|Bs], X, [Z|Zs]) :- dot(Row, X, Z0), Z is Z0+B, linear(Rows, Bs, X, Zs).

forward(net(W1, B1, W2, B2), X, H, P) :-
	hidden(W1, B1, X, H),
	linear(W2, B2, H, Zs),
	softmax(Zs, P).

softmax(Zs, P) :-
	max_list(Zs, Mx),
	exps(Zs, Mx, Es),
	sum_list(Es, S),
	divs(Es, S, P).
exps([], _, []).
exps([Z|Zs], M, [E|Es]) :- E is exp(Z-M), exps(Zs, M, Es).
divs([], _, []).
divs([E|Es], S, [P|Ps]) :- P is E/S, divs(Es, S, Ps).

mnn_predict(Net, X, P) :- forward(Net, X, _, P).

mnn_rank(Net, X, Classes, Ranked) :-
	mnn_predict(Net, X, P),
	pairs_keys_values(Ps, P, Classes),
	keysort(Ps, S), reverse(S, R),
	pairs_values(R, Ranked).

%!	mnn_train(+Net0, +Data, +Epochs, +Rate, -Net)
%	Data: list of Features-ClassIndex (ClassIndex counts from 1).
mnn_train(Net, _, 0, _, Net) :- !.
mnn_train(Net0, Data, E, Rate, Net) :-
	foldl(step(Rate), Data, Net0, Net1),
	E1 is E-1,
	mnn_train(Net1, Data, E1, Rate, Net).

step(Rate, X-Y, Net0, net(W1n, B1n, W2n, B2n)) :-
	Net0 = net(W1, B1, W2, B2),
	forward(Net0, X, H, P),
	out_delta(P, 1, Y, DZ2),
	update_rows(W2, DZ2, H, Rate, W2n),
	update_bias(B2, DZ2, Rate, B2n),
	transpose_(W2, W2T),
	hidden_delta(W2T, H, DZ2, DZ1),
	update_rows(W1, DZ1, X, Rate, W1n),
	update_bias(B1, DZ1, Rate, B1n).

out_delta([], _, _, []).
out_delta([P|Ps], I, Y, [D|Ds]) :- ( I =:= Y -> D is P-1 ; D = P ), I1 is I+1, out_delta(Ps, I1, Y, Ds).

update_rows([], [], _, _, []).
update_rows([Row|Rows], [D|Ds], In, R, [Row1|Rows1]) :-
	update_row(Row, In, D, R, Row1), update_rows(Rows, Ds, In, R, Rows1).
update_row([], [], _, _, []).
update_row([W|Ws], [X|Xs], D, R, [W1|Ws1]) :- W1 is W-R*D*X, update_row(Ws, Xs, D, R, Ws1).

update_bias([], [], _, []).
update_bias([B|Bs], [D|Ds], R, [B1|Bs1]) :- B1 is B-R*D, update_bias(Bs, Ds, R, Bs1).

hidden_delta([], [], _, []).
hidden_delta([Col|Cols], [H|Hs], DZ2, [D|Ds]) :-
	dot(Col, DZ2, Dh), D is Dh*(1-H*H), hidden_delta(Cols, Hs, DZ2, Ds).

transpose_([[]|_], []) :- !.
transpose_(M, [Col|Cols]) :-
	maplist([[H|T], H, T]>>true, M, Col, Rest),
	transpose_(Rest, Cols).

mnn_accuracy(Net, Data, Acc) :-
	length(Data, N),
	aggregate_all(count, ( member(X-Y, Data), mnn_predict(Net, X, P),
			       max_list(P, Mx), nth1(Y, P, Mx) ), C),
	( N =:= 0 -> Acc = 0 ; Acc is C/N ).

%!	mnn_explain(+Net, +FeatureNames, +ClassNames, -Rules)
%	Linearise the network (W2 x W1) and keep, for each class, the inputs
%	with the strongest positive influence.
mnn_explain(net(W1, _, W2, _), Fs, Cs, Rules) :-
	transpose_(W1, W1T),
	findall((prefers(C) :- Body)-Ws,
		( nth1(K, Cs, C), nth1(K, W2, Row),
		  findall(Inf-F, ( nth1(I, Fs, F), nth1(I, W1T, Col), dot(Row, Col, Inf), Inf > 0 ), IFs),
		  keysort(IFs, S), reverse(S, R),
		  ( length(Top, 3), append(Top, _, R) -> true ; Top = R ),
		  Top \== [],
		  pairs_values(Top, TopFs), pairs_keys(Top, Ws0),
		  maplist([W, W2r]>>(W2r is round(W*100)/100), Ws0, Ws),
		  maplist([F, feature(F)]>>true, TopFs, Gs),
		  goals_conj(Gs, Body) ),
		Rules).

goals_conj([G], G) :- !.
goals_conj([G|Gs], (G, B)) :- goals_conj(Gs, B).

mnn_save(File, MNN) :-
	setup_call_cleanup(open(File, write, S),
			   ( format(S, "% MNN weights, written by lc_mnn:mnn_save/2.~n", []),
			     format(S, "~q.~n", [MNN]) ),
			   close(S)).

mnn_load(File, MNN) :-
	exists_file(File),
	setup_call_cleanup(open(File, read, S), read_term(S, MNN, []), close(S)).
